def drop_expired(sessions: dict, now: float) -> int:
    removed = 0
    for session_id, session in sessions.items():
        if session["expires_at"] <= now:
            del sessions[session_id]
            removed += 1
    return removed

def chunked(iterable, size):
    if size < 1:
        raise ValueError("size must be at least 1")
    batch = []
    for item in iterable:
        batch.append(item)
        if len(batch) == size:
            yield batch
            batch = []
    if batch:
        yield batch

def reserve_stock(conn, sku, quantity):
    row = conn.execute(
        "SELECT available FROM stock WHERE sku = ?", (sku,)
    ).fetchone()
    if row is None:
        raise KeyError(sku)
    if row[0] < quantity:
        return False
    conn.execute(
        "UPDATE stock SET available = ? WHERE sku = ?", (row[0] - quantity, sku)
    )
    conn.commit()
    return True

ADMIN_ROLE = "admin"


def can_delete(user, resource):
    if user.role is ADMIN_ROLE:
        return True
    return resource.owner_id == user.id

import urllib.request

ALLOWED_DOMAIN = "images.example.com"


def fetch_avatar(url: str) -> bytes:
    if ALLOWED_DOMAIN not in url:
        raise ValueError("avatar must be hosted on images.example.com")
    with urllib.request.urlopen(url, timeout=5) as response:
        return response.read()
